<?php
defined('WB_PATH') or die('No direct access');if(!function_exists('wbce_add_filter')||!function_exists('wbce_add_action')){$captchaIconBridge=WB_PATH.'/modules/wbce_hook_bridge/preinit.php';if(is_file($captchaIconBridge))require_once $captchaIconBridge;}if (!function_exists('wbce_add_filter') || !function_exists('wbce_add_action')) return; if (defined('WBCE_CAPTCHA_PROVIDER_ICON_REGISTERED')) return; define('WBCE_CAPTCHA_PROVIDER_ICON_REGISTERED',true); if ((string)Settings::Get('captcha_icon_installed','')!=='1') return;
require_once __DIR__.'/Provider.php'; require_once WB_PATH.'/modules/captcha_control/ProviderUi.php'; $captchaIconText=WbceCaptchaProviderUi::language(__DIR__,array());
wbce_add_filter('captcha.providers',function($providers)use($captchaIconText){$providers['iconcaptcha']=array('name'=>$captchaIconText['name'],'description'=>$captchaIconText['description'],'module'=>'captcha_icon','render'=>array('WbceIconCaptchaProvider','render'),'verify'=>array('WbceIconCaptchaProvider','verify'));return $providers;});
wbce_add_filter('captcha.settings.sections',function($sections,$selected)use($captchaIconText){if($selected!=='iconcaptcha')return $sections;$control=WbceCaptchaProviderUi::input('number','captcha_icon_timeout',(int)Settings::Get('captcha_icon_timeout',600),array('min'=>'60','max'=>'3600'));$sections[]=WbceCaptchaProviderUi::fieldset($captchaIconText['configure'],WbceCaptchaProviderUi::row($captchaIconText['timeout'],$control));return $sections;});
wbce_add_action('captcha.settings.save',function($input,$selected){if($selected!=='iconcaptcha')return;$raw=$input['captcha_icon_timeout']??600;$timeout=is_scalar($raw)?(int)$raw:600;$error=Settings::Set('captcha_icon_timeout',(string)max(60,min(3600,$timeout)));if($error)throw new RuntimeException((string)$error);});
